import { Fragment, h, render } from 'preact';
import { useEffect, useMemo, useState } from 'preact/hooks';
import { searchManagement } from './managementSearch';
import '@vscode/codicons/dist/codicon.css';
import './style.css';

declare function acquireVsCodeApi(): { postMessage(message: unknown): void; getState<T>(): T | undefined; setState<T>(state: T): T };

type Area = 'overview' | 'library' | 'runs' | 'quality' | 'create' | 'operations';
type LayoutMode = 'compact' | 'expanded';

interface CoverageSnapshot {
    specName: string;
    percentage: number;
    totalEndpoints: number;
    coveredEndpoints: number;
    endpoints: Array<{ path: string; method: string; operationId?: string; covered: boolean; scenarios: string[]; missingTests: string[] }>;
    methodBreakdown: Array<{ method: string; total: number; covered: number; percentage: number }>;
    copilotInsights?: { quality: string; riskAssessment: string; recommendations: string[]; priorityEndpoints: Array<{ path: string; method: string; reason: string }> };
}

interface HealthSnapshot {
    totalFiles: number;
    totalScenarios: number;
    dryScore: number;
    orphanedFiles: string[];
    dependencyCount: number;
    dependencies?: Array<{ source: string; target: string }>;
}

interface BugHunterSnapshot {
    baseUrl: string;
    totalProbes: number;
    executedProbes: number;
    skippedProbes: number;
    completedAt: number;
    reproFile?: string;
    findings: Array<{ category: string; severity: string; method: string; path: string; expected: string; observed: string; curl?: string; karateScenario?: string }>;
    probes: Array<{ name: string; method: string; path: string; category?: string; status: 'executed' | 'skipped'; reason?: string; responseStatus?: number; durationMs?: number; findingId?: string }>;
}

interface Snapshot {
    folderName?: string;
    folderPath?: string;
    folders?: Array<{ name: string; path: string }>;
    featureCount?: number;
    features?: Array<{ path: string; scenarios: Array<{ name: string; tags: string[]; line: number; owner?: string; status?: string; zephyrKey?: string; flakiness?: number; flakinessTier?: 'stable' | 'watch' | 'flaky' | 'broken'; flakinessRuns?: number }> }>;
    runs?: Array<{ id: string; timestamp: number; status: string; error?: string; options?: { type: 'feature' | 'features' | 'folder' | 'tags' | 'scenario'; target: string | string[]; tags?: string[]; environment?: string; buildTool?: 'auto' | 'maven' | 'gradle' | 'cli'; parallel?: number; workingDirectory?: string; scenarioLine?: number; scenarioName?: string; runnerClass?: string; runnerMethod?: string; configDir?: string }; summary?: { totalScenarios: number; passed: number; failed: number; skipped?: number; passPercentage: number; executionTime?: string }; features?: Array<{ name: string; relativePath?: string; failed?: number; scenarios?: Array<{ name: string; status: string; error?: string; line?: number; tags?: string[] }> }> }>;
    findings?: Array<{ id: string; title?: string; state?: string; severity?: string; source?: string }>;
    runProfiles?: Array<{ id: string; name?: string; environment?: string }>;
    environments?: Array<{ id: string; name?: string }>;
    coverageReports?: CoverageSnapshot[];
    healthReports?: HealthSnapshot[];
}

interface TemplateOption { id: string; name: string; content: string; }
interface GenerationHistoryItem { id: string; timestamp: number; type: string; source: string; outputPath: string; }
interface GeneratedOutput { message: string; filePath: string; content: string; }

const vscode = acquireVsCodeApi();
const appIcon = document.body.dataset.appIcon || '';
const areas: Array<{ id: Area; label: string; icon: string }> = [
    { id: 'overview', label: 'Overview', icon: 'home' },
    { id: 'library', label: 'Test Library', icon: 'library' },
    { id: 'runs', label: 'Runs', icon: 'run-all' },
    { id: 'quality', label: 'Quality', icon: 'shield' },
    { id: 'create', label: 'Create & Import', icon: 'new-file' },
    { id: 'operations', label: 'Operations', icon: 'settings-gear' }
];

function send(command: string, payload: Record<string, unknown> = {}): void {
    vscode.postMessage({ command, ...payload });
}

function App() {
    const [activeArea, setActiveArea] = useState<Area>('overview');
    const [snapshot, setSnapshot] = useState<Snapshot>({ runs: [], findings: [] });
    const [coverage, setCoverage] = useState<CoverageSnapshot>();
    const [health, setHealth] = useState<HealthSnapshot>();
    const [bugHunter, setBugHunter] = useState<BugHunterSnapshot>();
    const [runActive, setRunActive] = useState(false);
    const [query, setQuery] = useState('');
    const [notice, setNotice] = useState<{ kind: 'error' | 'success'; text: string }>();
    const [selectedFile, setSelectedFile] = useState('');
    const [templates, setTemplates] = useState<TemplateOption[]>([]);
    const [generationHistory, setGenerationHistory] = useState<GenerationHistoryItem[]>([]);
    const [hasLearnedStyle, setHasLearnedStyle] = useState(false);
    const [generatedOutput, setGeneratedOutput] = useState<GeneratedOutput>();
    const [coverageSpecPaths, setCoverageSpecPaths] = useState<string[]>([]);
    const [coverageFeaturePaths, setCoverageFeaturePaths] = useState<string[]>([]);
    const layoutMode: LayoutMode = document.body.dataset.managementLayout === 'expanded' ? 'expanded' : 'compact';

    useEffect(() => {
        const onMessage = (event: MessageEvent<{ type?: string; data?: Snapshot | CoverageSnapshot | HealthSnapshot | BugHunterSnapshot | TemplateOption[] | GenerationHistoryItem[] | string[]; message?: string; filePath?: string; content?: string }>) => {
            if (event.data.type === 'managementSnapshot') {
                const next = (event.data.data as Snapshot) || {};
                setSnapshot(next);
                if (next.coverageReports?.[0]) setCoverage(next.coverageReports[0]);
                if (next.healthReports?.[0]) setHealth(next.healthReports[0]);
            }
            if (event.data.type === 'coverageReport') setCoverage(event.data.data as CoverageSnapshot);
            if (event.data.type === 'healthReport') setHealth(event.data.data as HealthSnapshot);
            if (event.data.type === 'bugHunterReport') setBugHunter(event.data.data as BugHunterSnapshot);
            if (event.data.type === 'coverageSpecsSelected') setCoverageSpecPaths((event.data.data as string[]) || []);
            if (event.data.type === 'coverageFeaturesSelected') setCoverageFeaturePaths((event.data.data as string[]) || []);
            if (event.data.type === 'templates') setTemplates((event.data.data as TemplateOption[]) || []);
            if (event.data.type === 'history') setGenerationHistory((event.data.data as GenerationHistoryItem[]) || []);
            if (event.data.type === 'styleLearned') setHasLearnedStyle(true);
            if (event.data.type === 'fileSelected' && event.data.filePath) setSelectedFile(event.data.filePath);
            if (event.data.type === 'success' && event.data.filePath && event.data.content) setGeneratedOutput({ message: event.data.message || 'Generation complete', filePath: event.data.filePath, content: event.data.content });
            if (event.data.type === 'executionState') setRunActive(Boolean((event.data as { running?: unknown }).running));
            if ((event.data.type === 'error' || event.data.type === 'success') && event.data.message) setNotice({ kind: event.data.type, text: event.data.message });
            if (event.data.type === 'navigateManagement' && areas.some(area => area.id === (event.data as { area?: Area }).area)) setActiveArea((event.data as { area: Area }).area);
        };
        window.addEventListener('message', onMessage);
        send('getManagementSnapshot');
        send('managementReady');
        send('getTemplates');
        send('getHistory');
        return () => window.removeEventListener('message', onMessage);
    }, []);

    const filteredRuns = useMemo(() => (snapshot.runs || []).filter(run => `${run.id} ${run.status} ${run.options?.environment || ''} ${run.options?.target || ''}`.toLowerCase().includes(query.toLowerCase())), [snapshot.runs, query]);
    const failedRuns = (snapshot.runs || []).filter(run => run.status !== 'success');
    const latestRun = snapshot.runs?.[0];
    return <main class={`management-shell layout-${layoutMode}`}>
        <aside class="rail" aria-label="Karate test management navigation">
            <div class="rail-brand" aria-label="Karate Test Management"><img src={appIcon} alt="" /> <span class="rail-label">Karate</span></div>
            <button class={`rail-primary ${activeArea === 'create' ? 'is-active' : ''}`} aria-label="Generate tests" title="Generate tests" onClick={() => setActiveArea('create')}>
                <span class="codicon codicon-new-file" aria-hidden="true" /> <span class="rail-label">Generate tests</span>
            </button>
            <label class="rail-search"><span class="codicon codicon-search" aria-hidden="true" /><span class="sr-only">Search tests, runs, and findings</span><input value={query} onInput={event => setQuery((event.target as HTMLInputElement).value)} placeholder="Search tests, runs" /></label>
            <div class="rail-context" aria-label="Latest execution status">
                <span class="rail-context-label">STATUS</span>
                <button class={`rail-status ${runActive ? 'is-running' : latestRun ? (latestRun.status === 'success' ? 'is-success' : 'is-failed') : ''}`} title="Open runs" onClick={() => setActiveArea('runs')}>
                    <span class={`codicon codicon-${runActive ? 'loading codicon-modifier-spin' : latestRun ? (latestRun.status === 'success' ? 'pass' : 'error') : 'circle-outline'}`} aria-hidden="true" />
                    <span class="rail-label">{runActive ? 'Running tests' : latestRun ? (latestRun.status === 'success' ? 'Latest run passed' : 'Latest run needs review') : 'No runs yet'}</span>
                </button>
            </div>
            <nav>
                {areas.map(area => <button class={`rail-item ${activeArea === area.id ? 'is-active' : ''}`} aria-label={area.label} title={area.label} aria-current={activeArea === area.id ? 'page' : undefined} onClick={() => setActiveArea(area.id)}>
                    <span class={`codicon codicon-${area.icon}`} aria-hidden="true" /> <span class="rail-label">{area.label}</span>
                </button>)}
            </nav>
            <button class="rail-foot" aria-label={layoutMode === 'compact' ? 'Open full workspace' : 'Return to sidebar'} title={layoutMode === 'compact' ? 'Open full workspace' : 'Return to sidebar'} onClick={() => send(layoutMode === 'compact' ? 'openExpandedWorkspace' : 'focusManagementSidebar')}>
                <span class={`codicon codicon-${layoutMode === 'compact' ? 'open-preview' : 'layout-sidebar-left'}`} aria-hidden="true" /> <span class="rail-label">{layoutMode === 'compact' ? 'Open full workspace' : 'Return to sidebar'}</span>
            </button>
        </aside>
        <section class="workspace">
            <header class="topbar">
                <div class="product-mark" aria-label="Karate Test Management"><img src={appIcon} alt="" /><span>Karate</span></div>
                <label class="workspace-picker"><span class="eyebrow">WORKSPACE</span><select value={snapshot.folderPath || ''} onChange={event => send('getManagementSnapshot', { folderPath: (event.target as HTMLSelectElement).value })}>{(snapshot.folders || [{ name: snapshot.folderName || 'Karate project', path: snapshot.folderPath || '' }]).map(folder => <option value={folder.path}>{folder.name}</option>)}</select></label>
                <label class="search"><span class="codicon codicon-search" aria-hidden="true" /><span class="sr-only">Search runs</span><input value={query} onInput={event => setQuery((event.target as HTMLInputElement).value)} placeholder="Search tests, runs, findings" /></label>
                <button class={`run-status ${runActive ? 'is-running' : latestRun ? (latestRun.status === 'success' ? 'is-success' : 'is-failed') : ''}`} onClick={() => setActiveArea('runs')} title="Open runs">{runActive ? <><span class="codicon codicon-loading codicon-modifier-spin" aria-hidden="true" /> Running tests</> : latestRun ? <><span class={`codicon codicon-${latestRun.status === 'success' ? 'pass' : 'error'}`} aria-hidden="true" /> Latest: {latestRun.status === 'success' ? 'passed' : latestRun.status}</> : <><span class="codicon codicon-circle-outline" aria-hidden="true" /> No runs yet</>}</button>
                <div class="topbar-actions">{layoutMode === 'compact' ? <button class="layout-toggle" title="Open the full test management workspace in an editor tab" onClick={() => send('openExpandedWorkspace')}><span class="codicon codicon-open-preview" aria-hidden="true" /><span class="layout-toggle-label">Open</span></button> : <button class="layout-toggle" title="Return to the compact sidebar" onClick={() => send('focusManagementSidebar')}><span class="codicon codicon-layout-sidebar-left" aria-hidden="true" /><span class="layout-toggle-label">Sidebar</span></button>}<button class="primary-action" disabled={runActive} onClick={() => send('executeExtensionCommand', { commandId: 'karate-dsl.runFolder', folderPath: snapshot.folderPath })}><span class="codicon codicon-play" aria-hidden="true" /> <span class="run-action-label">{runActive ? 'Running…' : 'Run tests'}</span></button></div>
            </header>
            {query.trim() && <GlobalSearch snapshot={snapshot} query={query} onNavigate={setActiveArea} />}
            {activeArea === 'overview' && <Overview snapshot={snapshot} failedRuns={failedRuns} onNavigate={setActiveArea} />}
            {activeArea === 'library' && <Library featureCount={snapshot.featureCount || 0} features={snapshot.features || []} query={query} folderPath={snapshot.folderPath} />}
            {activeArea === 'runs' && <ManagementRuns runs={filteredRuns} profiles={snapshot.runProfiles || []} environments={snapshot.environments || []} folderPath={snapshot.folderPath} runActive={runActive} />}
            {activeArea === 'quality' && <ManagementQuality findings={snapshot.findings || []} coverage={coverage} health={health} folderPath={snapshot.folderPath} query={query} specPaths={coverageSpecPaths} featurePaths={coverageFeaturePaths} />}
            {activeArea === 'create' && <Create templates={templates} selectedFile={selectedFile} generatedOutput={generatedOutput} onFileConsumed={() => setSelectedFile('')} />}
            {activeArea === 'operations' && <ManagementOperations bugHunter={bugHunter} onNavigate={setActiveArea} templates={templates} history={generationHistory} hasLearnedStyle={hasLearnedStyle} />}
            {notice && <div class={`notice ${notice.kind}`} role="status"><span>{notice.text}</span><button aria-label="Dismiss message" onClick={() => setNotice(undefined)}><span class="codicon codicon-close" aria-hidden="true" /></button></div>}
        </section>
    </main>;
}

function GlobalSearch({ snapshot, query, onNavigate }: { snapshot: Snapshot; query: string; onNavigate: (area: Area) => void }) { const { scenarios, runs, findings, total } = searchManagement(snapshot, query); return <section class="global-search-results" aria-live="polite"><div class="panel"><div class="panel-heading"><div><h2>Search results</h2><p>{total ? `Matches across this workspace for “${query.trim()}”` : `No indexed matches for “${query.trim()}”`}</p></div><span class="status-pill">{total}</span></div>{total > 0 && <ul>{scenarios.map(({ feature, scenario }) => <li><span class="codicon codicon-file-code" aria-hidden="true" /><div><strong>{scenario.name}</strong><small>Scenario · {feature.path}</small></div><button class="text-action" onClick={() => onNavigate('library')}>Open library</button></li>)}{runs.map(run => <li><span class="codicon codicon-run-all" aria-hidden="true" /><div><strong>Run {run.id.slice(0, 8)}</strong><small>Run · {run.status} · {new Date(run.timestamp).toLocaleString()}</small></div><button class="text-action" onClick={() => onNavigate('runs')}>Open runs</button></li>)}{findings.map(finding => <li><span class="codicon codicon-shield" aria-hidden="true" /><div><strong>{finding.title || 'Quality finding'}</strong><small>Quality · {finding.state || 'New'} · {finding.severity || 'Normal'}</small></div><button class="text-action" onClick={() => onNavigate('quality')}>Open quality</button></li>)}</ul>}</div></section>; }

function Overview({ snapshot, failedRuns, onNavigate }: { snapshot: Snapshot; failedRuns: Snapshot['runs']; onNavigate: (area: Area) => void }) {
    const total = snapshot.runs?.[0]?.summary?.totalScenarios || 0;
    const passed = snapshot.runs?.[0]?.summary?.passed || 0;
    const isNewWorkspace = !snapshot.featureCount && !snapshot.runs?.length && !snapshot.findings?.length;
    if (isNewWorkspace) return <section class="area onboarding" aria-labelledby="overview-title"><span class="eyebrow">KARATE TEST MANAGEMENT</span><h1 id="overview-title">Turn your API contract into a living test suite.</h1><p>Generate structured Karate coverage first. The library, runs, and quality queue will grow from there.</p><div class="onboarding-actions"><button class="primary-action" onClick={() => onNavigate('create')}><span class="codicon codicon-new-file" aria-hidden="true" /> Generate tests</button><button onClick={() => send('openExpandedWorkspace')}><span class="codicon codicon-open-preview" aria-hidden="true" /> Open full workspace</button></div><dl class="onboarding-steps"><div><dt>01</dt><dd><strong>Import a source</strong><span>OpenAPI, Confluence, Postman, HAR, or GraphQL.</span></dd></div><div><dt>02</dt><dd><strong>Generate with intent</strong><span>Choose methods, scenario types, AI enhancement, and templates.</span></dd></div><div><dt>03</dt><dd><strong>Run and improve</strong><span>Track execution, coverage, and repair work in one place.</span></dd></div></dl></section>;
    return <section class="area" aria-labelledby="overview-title">
        <div class="area-heading"><div><span class="eyebrow">CONTROL CENTRE</span><h1 id="overview-title">Test health at a glance</h1><p>Prioritised work across your Karate project.</p></div><button class="text-action" onClick={() => onNavigate('quality')}>View quality queue <span class="codicon codicon-arrow-right" /></button></div>
        <div class="metric-row">
            <Metric label="Latest pass rate" value={total ? `${Math.round((passed / total) * 100)}%` : '—'} note={total ? `${passed} of ${total} scenarios passed` : 'Run a test suite to establish a baseline'} />
            <Metric label="Runs needing attention" value={String(failedRuns?.length || 0)} note="Failed or errored recent runs" emphasis={(failedRuns?.length || 0) > 0} />
            <Metric label="Feature files" value={String(snapshot.featureCount || 0)} note="Discovered in this workspace" />
            <Metric label="Open findings" value={String(snapshot.findings?.filter(item => item.state !== 'Verified').length || 0)} note="Coverage, health, and stability work" />
        </div>
        <div class="panel"><div class="panel-heading"><div><h2>Priority queue</h2><p>Start with work that affects confidence in the suite.</p></div><span class="status-pill">Live workspace</span></div>
            {(failedRuns?.length || snapshot.findings?.length) ? <ul class="queue">{failedRuns?.slice(0, 4).map(run => <li><span class="queue-marker danger" /><div><strong>Investigate failed run</strong><small>{new Date(run.timestamp).toLocaleString()}</small></div><button onClick={() => onNavigate('runs')}>Open runs</button></li>)}{snapshot.findings?.slice(0, 4).map(finding => <li><span class="queue-marker" /><div><strong>{finding.title || 'Quality finding'}</strong><small>{finding.state || 'New'} · {finding.severity || 'Normal'}</small></div><button onClick={() => onNavigate('quality')}>Review</button></li>)}</ul> : <Empty title="Your queue is clear" detail="Run tests, analyse coverage, or import a spec to create actionable work." action="Create or import" onAction={() => onNavigate('create')} />}</div>
    </section>;
}

function Metric({ label, value, note, emphasis = false }: { label: string; value: string; note: string; emphasis?: boolean }) { return <article class={`metric ${emphasis ? 'metric-warning' : ''}`}><span>{label}</span><strong>{value}</strong><small>{note}</small></article>; }

function ManagementRuns({ runs = [], profiles, environments, folderPath, runActive }: { runs: NonNullable<Snapshot['runs']>; profiles: NonNullable<Snapshot['runProfiles']>; environments: NonNullable<Snapshot['environments']>; folderPath?: string; runActive: boolean }) {
    const [name, setName] = useState('');
    const [environment, setEnvironment] = useState('');
    const [parallel, setParallel] = useState('1');
    const [selected, setSelected] = useState<NonNullable<Snapshot['runs']>[number]>();
    const [compare, setCompare] = useState(false);
    const selectedIndex = selected ? runs.findIndex(run => run.id === selected.id) : -1;
    const previous = selectedIndex >= 0 ? runs[selectedIndex + 1] : undefined;
    const trendRuns = [...runs.slice(0, 10)].reverse();
    const saveProfile = () => {
        if (!name.trim()) return;
        send('createRunProfile', { name, environment, parallel: Number(parallel), folderPath });
        setName(''); setEnvironment(''); setParallel('1');
    };
    return <section class="area">
        <div class="area-heading"><div><span class="eyebrow">EXECUTION</span><h1>Runs</h1><p>{runActive ? 'A test run is active. Results will appear here when it completes.' : 'History, profiles, trends, and scenario-level failure triage.'}</p></div><div class="heading-actions"><button disabled={runActive} onClick={() => send('executeExtensionCommand', { commandId: 'karate-dsl.runByTags', folderPath })}><span class="codicon codicon-tag" /> Run by tags</button><button class="primary-action" disabled={runActive} onClick={() => send('executeExtensionCommand', { commandId: 'karate-dsl.runFolder', folderPath })}><span class="codicon codicon-play" /> {runActive ? 'Running…' : 'Run all tests'}</button></div></div>
        <div class="profile-bar"><div><strong>Run profiles</strong><small>{profiles.length ? <span class="profile-list">{profiles.map(profile => <button disabled={runActive} onClick={() => send('runProfile', { id: profile.id, folderPath })}>{profile.name || 'Unnamed'}{profile.environment ? ` · ${profile.environment}` : ''}</button>)}</span> : 'Save repeatable environment and worker choices.'}</small></div><label><span class="sr-only">Profile name</span><input value={name} onInput={event => setName((event.target as HTMLInputElement).value)} placeholder="Profile name" /></label><label><span class="sr-only">Environment</span><input list="known-environments" value={environment} onInput={event => setEnvironment((event.target as HTMLInputElement).value)} placeholder="Environment (optional)" /></label><datalist id="known-environments">{environments.map(item => <option value={item.name || ''} />)}</datalist><label><span class="sr-only">Parallel workers</span><input class="parallel-input" type="number" min="1" value={parallel} onInput={event => setParallel((event.target as HTMLInputElement).value)} /></label><button disabled={!name.trim()} onClick={saveProfile}>Save profile</button></div>
        {trendRuns.length > 1 && <section class="panel run-trend"><div class="panel-heading"><div><h2>Pass-rate trend</h2><p>Last {trendRuns.length} executions</p></div></div><div class="trend-bars" aria-label="Pass-rate history">{trendRuns.map(run => <button title={`${new Date(run.timestamp).toLocaleString()}: ${run.summary?.passPercentage ?? 0}%`} onClick={() => setSelected(run)}><span style={{ height: `${Math.max(3, run.summary?.passPercentage || 0)}%` }} class={run.status === 'success' ? 'is-success' : 'is-failed'} /></button>)}</div></section>}
        <div class="panel data-panel">{runs.length ? <table><thead><tr><th>Run</th><th>When</th><th>Outcome</th><th>Scenarios</th><th>Pass rate</th><th>Duration</th></tr></thead><tbody>{runs.map(run => <tr class="clickable-row" tabIndex={0} onClick={() => { setSelected(run); setCompare(false); }} onKeyDown={event => { if (event.key === 'Enter' || event.key === ' ') setSelected(run); }}><td>{run.id.slice(0, 8)}</td><td>{new Date(run.timestamp).toLocaleString()}</td><td><span class={`status ${run.status === 'success' ? 'success' : 'failed'}`}>{run.status}</span></td><td>{run.summary?.totalScenarios ?? '—'}</td><td>{run.summary?.passPercentage ?? '—'}%</td><td>{run.summary?.executionTime || '—'}</td></tr>)}</tbody></table> : <Empty title="No runs recorded" detail={runActive ? 'Execution is in progress.' : 'Run a feature, folder, or tagged selection to build history.'} action={runActive ? undefined : 'Run all tests'} onAction={runActive ? undefined : () => send('executeExtensionCommand', { commandId: 'karate-dsl.runFolder', folderPath })} />}</div>
        {selected && <ManagementRunDetail run={selected} previous={previous} compare={compare} onCompare={() => setCompare(value => !value)} folderPath={folderPath} onClose={() => setSelected(undefined)} />}
    </section>;
}

function ManagementRunDetail({ run, previous, compare, onCompare, folderPath, onClose }: { run: NonNullable<Snapshot['runs']>[number]; previous?: NonNullable<Snapshot['runs']>[number]; compare: boolean; onCompare: () => void; folderPath?: string; onClose: () => void }) {
    const scenarios = run.features?.flatMap(feature => (feature.scenarios || []).map(scenario => ({ feature, scenario }))) || [];
    const passDelta = previous ? (run.summary?.passPercentage || 0) - (previous.summary?.passPercentage || 0) : 0;
    return <aside class="run-detail wide-detail" aria-label="Run details"><div class="panel-heading"><div><h2>Run {run.id.slice(0, 8)}</h2><p>{run.summary?.executionTime || 'Execution details'} · {run.summary?.passed || 0} passed, {run.summary?.failed || 0} failed</p></div><div class="detail-actions">{previous && <button class="text-action" onClick={onCompare}><span class="codicon codicon-git-compare" /> {compare ? 'Hide comparison' : 'Compare previous'}</button>}<button class="text-action" onClick={() => send('exportRunReport', { id: run.id, folderPath })}><span class="codicon codicon-export" /> Export</button>{run.options && <button class="text-action" onClick={() => send('rerunRun', { options: run.options, folderPath })}><span class="codicon codicon-refresh" /> Rerun</button>}<button aria-label="Close run details" onClick={onClose}><span class="codicon codicon-close" /></button></div></div>
        {compare && previous && <div class="run-comparison"><div><span>Pass-rate change</span><strong class={passDelta >= 0 ? 'positive' : 'negative'}>{passDelta >= 0 ? '+' : ''}{passDelta.toFixed(1)} points</strong></div><div><span>Failed scenarios</span><strong>{previous.summary?.failed || 0} → {run.summary?.failed || 0}</strong></div><div><span>Scenario count</span><strong>{previous.summary?.totalScenarios || 0} → {run.summary?.totalScenarios || 0}</strong></div></div>}
        {run.error && <p class="run-error">{run.error}</p>}
        <div class="scenario-list"><div class="scenario-list-heading"><strong>Scenario results</strong><span>{scenarios.length} recorded</span></div>{scenarios.length ? scenarios.map(({ feature, scenario }) => <article class="scenario-result"><span class={`scenario-state ${scenario.status === 'passed' ? 'passed' : 'failed'}`}><span class={`codicon codicon-${scenario.status === 'passed' ? 'pass' : 'error'}`} /></span><div><strong>{scenario.name}</strong><small>{feature.relativePath || feature.name}{scenario.error ? ` · ${scenario.error}` : ''}</small></div><div class="scenario-actions">{scenario.line && <button class="text-action" onClick={() => send('openScenario', { featurePath: feature.relativePath || feature.name, line: scenario.line, folderPath })}>Open</button>}{scenario.status !== 'passed' && <button class="text-action" onClick={() => send('requestScenarioRepair', { featurePath: feature.relativePath || feature.name, scenarioName: scenario.name, errorMessage: scenario.error || run.error || '', scenarioTags: scenario.tags, scenarioLine: scenario.line, folderPath })}>Review repair</button>}</div></article>) : <Empty title="No scenario detail recorded" detail="This execution result contains summary information only." />}</div>
    </aside>;
}

function ManagementQuality({ findings, coverage, health, folderPath, query, specPaths, featurePaths }: { findings: NonNullable<Snapshot['findings']>; coverage?: CoverageSnapshot; health?: HealthSnapshot; folderPath?: string; query: string; specPaths: string[]; featurePaths: string[] }) {
    const [state, setState] = useState('Open');
    const [source, setSource] = useState('All');
    const [coverageOpen, setCoverageOpen] = useState(false);
    const [useCopilot, setUseCopilot] = useState(false);
    const normalized = query.toLowerCase();
    const visible = findings.filter(item => (state === 'All' || (state === 'Open' ? item.state !== 'Verified' : item.state === state)) && (source === 'All' || item.source === source) && (!normalized || `${item.title || ''} ${item.source || ''} ${item.state || ''} ${item.severity || ''}`.toLowerCase().includes(normalized)));
    const sources = [...new Set(findings.map(item => item.source).filter(Boolean))];
    const analyze = () => send('analyzeCoverage', { specPaths, featurePaths, useCopilot, folderPath });
    return <section class="area"><div class="area-heading"><div><span class="eyebrow">ASSURANCE</span><h1>Quality</h1><p>Coverage, health, flakiness, and specification change impact.</p></div><div class="quality-actions"><button onClick={() => send('executeExtensionCommand', { commandId: 'karate-dsl.checkSpecChanges', folderPath })}>Check spec changes</button><button onClick={() => send('executeExtensionCommand', { commandId: 'karate-dsl.analyzeProjectHealth', folderPath })}>Analyse health</button><button class="primary-action" onClick={() => setCoverageOpen(value => !value)}><span class="codicon codicon-pulse" /> {coverageOpen ? 'Close coverage setup' : 'Analyse coverage'}</button></div></div>
        {coverageOpen && <section class="coverage-workbench panel"><div class="panel-heading"><div><h2>Coverage analysis scope</h2><p>Compare selected OpenAPI contracts with an explicit Karate feature set.</p></div><span class="status-pill">{specPaths.length} spec · {featurePaths.length} feature</span></div><div class="coverage-inputs"><CoverageInput label="OpenAPI specifications" paths={specPaths} action="Choose specs" onChoose={() => send('selectCoverageSpecs', { folderPath })} /><CoverageInput label="Karate feature files" paths={featurePaths} action="Choose features" onChoose={() => send('selectCoverageFeatures', { folderPath })} /></div><div class="coverage-runbar"><label><input type="checkbox" checked={useCopilot} onChange={event => setUseCopilot((event.target as HTMLInputElement).checked)} /> Add AI risk insights and missing-test suggestions</label><button class="primary-action" disabled={!specPaths.length || !featurePaths.length} onClick={analyze}><span class="codicon codicon-run-all" /> Run coverage analysis</button></div>{(!specPaths.length || !featurePaths.length) && <p class="coverage-requirement"><span class="codicon codicon-info" /> Both inputs are required. Coverage will never run against an implicit or empty feature scope.</p>}</section>}
        {health && <ManagementHealthReport report={health} />}
        {coverage && <ManagementCoverageReport report={coverage} featurePaths={featurePaths} folderPath={folderPath} onRefresh={specPaths.length && featurePaths.length ? analyze : undefined} />}
        {findings.length > 0 && <div class="filter-bar"><label>State <select value={state} onChange={event => setState((event.target as HTMLSelectElement).value)}><option>Open</option><option>All</option><option>New</option><option>Investigating</option><option>Fixed</option><option>Verified</option></select></label><label>Source <select value={source} onChange={event => setSource((event.target as HTMLSelectElement).value)}><option>All</option>{sources.map(value => <option>{value}</option>)}</select></label><span>{visible.length} finding{visible.length === 1 ? '' : 's'}</span></div>}
        <div class="panel data-panel">{visible.length ? <table><thead><tr><th>Finding</th><th>Source</th><th>State</th><th>Severity</th><th /></tr></thead><tbody>{visible.map(item => { const next = nextQualityState(item.state || 'New'); return <tr><td>{item.title || item.id}</td><td>{item.source || 'manual'}</td><td>{item.state || 'New'}</td><td>{item.severity || 'Normal'}</td><td>{next && <button class="text-action" onClick={() => send('advanceQualityFinding', { id: item.id, nextState: next, folderPath })}>Mark {next}</button>}</td></tr>; })}</tbody></table> : <Empty title={findings.length ? 'No findings match these filters' : 'No quality findings yet'} detail={findings.length ? 'Adjust the filters or search.' : 'Analyse coverage or project health to start a managed queue.'} action={findings.length ? undefined : 'Analyse coverage'} onAction={findings.length ? undefined : () => setCoverageOpen(true)} />}</div>
    </section>;
}

function CoverageInput({ label, paths, action, onChoose }: { label: string; paths: string[]; action: string; onChoose: () => void }) {
    return <div class="coverage-input"><div><strong>{label}</strong><span>{paths.length ? paths.map(displayFileName).join(' · ') : 'Nothing selected'}</span></div><button onClick={onChoose}><span class="codicon codicon-folder-opened" /> {action}</button></div>;
}

function ManagementCoverageReport({ report, featurePaths, folderPath, onRefresh }: { report: CoverageSnapshot; featurePaths: string[]; folderPath?: string; onRefresh?: () => void }) {
    return <section class="coverage-report panel"><div class="panel-heading"><div><h2>Coverage · {report.specName}</h2><p>{report.coveredEndpoints} of {report.totalEndpoints} endpoints covered using {featurePaths.length} selected feature file{featurePaths.length === 1 ? '' : 's'}</p></div><div class="detail-actions">{onRefresh && <button class="text-action" onClick={onRefresh}><span class="codicon codicon-refresh" /> Refresh</button>}<button class="text-action" onClick={() => send('exportCoverageReport', { folderPath })}><span class="codicon codicon-export" /> Export HTML</button><strong class="coverage-percentage">{report.percentage.toFixed(1)}%</strong></div></div><div class="coverage-methods">{report.methodBreakdown.map(method => <div><strong>{method.method}</strong><span>{method.covered}/{method.total} · {method.percentage.toFixed(0)}%</span></div>)}</div>{report.copilotInsights && <div class="coverage-insights"><div><span>AI quality assessment</span><strong>{report.copilotInsights.quality}</strong><p>{report.copilotInsights.riskAssessment}</p></div><div><span>Recommendations</span><ul>{report.copilotInsights.recommendations.map(item => <li>{item}</li>)}</ul></div></div>}<div class="endpoint-coverage-list">{report.endpoints.map(endpoint => <details class={endpoint.covered ? 'is-covered' : 'is-gap'}><summary><span class={`codicon codicon-${endpoint.covered ? 'pass' : 'warning'}`} /><code>{endpoint.method.toUpperCase()} {endpoint.path}</code><span>{endpoint.covered ? `${endpoint.scenarios.length} matching scenario${endpoint.scenarios.length === 1 ? '' : 's'}` : 'Coverage gap'}</span></summary><div class="endpoint-evidence">{endpoint.scenarios.length > 0 && <div><strong>Matching scenarios</strong><ul>{endpoint.scenarios.map(scenario => <li>{scenario}</li>)}</ul></div>}{endpoint.missingTests.length > 0 && <div><strong>Suggested coverage</strong><ul>{endpoint.missingTests.map(item => <li>{item}</li>)}</ul></div>}{!endpoint.covered && <div class="endpoint-actions"><button onClick={() => send('generateCoverageTest', { endpoint: { path: endpoint.path, method: endpoint.method, operationId: endpoint.operationId }, featurePaths, useCopilot: false, folderPath })}>Generate test</button><button onClick={() => send('generateCoverageTest', { endpoint: { path: endpoint.path, method: endpoint.method, operationId: endpoint.operationId }, featurePaths, useCopilot: true, folderPath })}>Generate with AI</button></div>}</div></details>)}</div></section>;
}

function ManagementHealthReport({ report }: { report: HealthSnapshot }) {
    return <section class="health-report panel"><div class="panel-heading"><div><h2>Project health</h2><p>Dependency and reuse signals from the selected workspace.</p></div><span class="status-pill">Fresh analysis</span></div><div class="health-metrics"><Metric label="Feature files" value={String(report.totalFiles)} note="Indexed feature files" /><Metric label="Scenarios" value={String(report.totalScenarios)} note="Across this folder" /><Metric label="Reusability" value={`${report.dryScore}%`} note={`${report.dependencyCount} feature dependencies`} /><Metric label="Potentially unused" value={String(report.orphanedFiles.length)} note="Reusable files with no callers" emphasis={report.orphanedFiles.length > 0} /></div>{Boolean(report.dependencies?.length) && <div class="dependency-map"><div class="subsection-heading"><strong>Feature dependency map</strong><span>Resolved read() and call relationships</span></div>{report.dependencies!.slice(0, 100).map(edge => <div class="dependency-edge"><code>{edge.source}</code><span class="codicon codicon-arrow-right" /><code>{edge.target}</code></div>)}</div>}{report.orphanedFiles.length > 0 && <div class="health-orphans"><strong>Review unused reusable features</strong><span>{report.orphanedFiles.slice(0, 20).join(' · ')}</span></div>}</section>;
}

function ManagementOperations({ bugHunter, onNavigate, templates, history, hasLearnedStyle }: { bugHunter?: BugHunterSnapshot; onNavigate: (area: Area) => void; templates: TemplateOption[]; history: GenerationHistoryItem[]; hasLearnedStyle: boolean }) {
    return <section class="area"><div class="area-heading"><div><span class="eyebrow">OPERATIONS</span><h1>Operations</h1><p>Investigate live APIs, personalise generation, and manage integrations.</p></div></div>{bugHunter && <ManagementBugHunterReport report={bugHunter} />}<div class="panel operations-list"><Operation title="API Bug Hunter" detail="Run bounded, allowlisted probes against an API specification." action="Start Bug Hunter" command="karate-dsl.huntApiBugs" /><Operation title="CI repair queue" detail="Review CI failures in Quality and apply AI suggestions only after confirmation." action="Review queue" onAction={() => onNavigate('quality')} /><Operation title="Zephyr publishing" detail="Set the Zephyr credential used for publishing traceability and results." action="Set Zephyr token" command="karate-dsl.setZephyrToken" /><Operation title="AI credentials" detail="Set the AI provider or GitHub credential used by generation and repair." action="Set AI key" command="karate-dsl.setClaudeApiKey" /><Operation title="MCP connection" detail="View connection details for supported automation clients." action="View connection" command="karate-dsl.showMcpConnectionInfo" /><Operation title="Workspace settings" detail="Manage execution and integration preferences." action="Open settings" command="workbench.action.openSettings" /><Operation title="Bug reporting" detail="Open a prefilled GitHub issue with optional context. No usage telemetry is collected." action="Report a bug" onAction={() => send('reportBug', { activeArea: 'operations' })} /></div><Personalize templates={templates} history={history} hasLearnedStyle={hasLearnedStyle} /></section>;
}

function ManagementBugHunterReport({ report }: { report: BugHunterSnapshot }) {
    return <section class="bug-hunter-report panel"><div class="panel-heading"><div><h2>Bug Hunter · {report.baseUrl}</h2><p>{report.executedProbes} executed, {report.skippedProbes} skipped · {new Date(report.completedAt).toLocaleString()}</p></div><strong class={report.findings.length ? 'finding-total has-findings' : 'finding-total'}>{report.findings.length} finding{report.findings.length === 1 ? '' : 's'}</strong></div><div class="bug-metrics"><Metric label="Probe candidates" value={String(report.totalProbes)} note="Built from this specification" /><Metric label="Executed" value={String(report.executedProbes)} note="Within configured limits" /><Metric label="Skipped" value={String(report.skippedProbes)} note="Guardrails or preconditions" /><Metric label="Repro feature" value={report.reproFile ? 'Ready' : '—'} note={report.reproFile || 'No repro created'} /></div>{report.findings.map(finding => <details class="bug-finding"><summary><span class={`status severity-${finding.severity}`}>{finding.severity}</span><code>{finding.method} {finding.path}</code><strong>{finding.category}</strong></summary><div class="bug-evidence"><div><span>Expected</span><pre>{finding.expected}</pre></div><div><span>Observed</span><pre>{finding.observed}</pre></div>{finding.curl && <div class="full"><span>curl reproducer</span><pre>{finding.curl}</pre></div>}{finding.karateScenario && <details class="full"><summary>Generated Karate scenario</summary><pre>{finding.karateScenario}</pre></details>}</div></details>)}<div class="probe-trace"><div class="subsection-heading"><strong>Probe trace</strong><span>Every executed and skipped guardrail decision</span></div>{report.probes.length ? <table><thead><tr><th>Probe</th><th>Category</th><th>Status</th><th>HTTP</th><th>Details</th></tr></thead><tbody>{report.probes.map(probe => <tr><td><code>{probe.method} {probe.path}</code><small>{probe.name}</small></td><td>{probe.category || '—'}</td><td><span class={`status ${probe.status}`}>{probe.status}</span></td><td>{probe.responseStatus ?? '—'}{probe.durationMs !== undefined ? ` · ${probe.durationMs}ms` : ''}</td><td>{probe.reason || (probe.findingId ? `Finding ${probe.findingId}` : 'No finding')}</td></tr>)}</tbody></table> : <Empty title="No probes built" detail="The selected specification did not produce probe candidates." />}</div></section>;
}

function displayFileName(value: string): string { return value.split(/[\\/]/).pop() || value; }
function Library({ featureCount, features, query, folderPath }: { featureCount: number; features: NonNullable<Snapshot['features']>; query: string; folderPath?: string }) { const [selected, setSelected] = useState<{ path: string; name: string; owner?: string; status?: string; zephyrKey?: string }>(); const normalized = query.trim().toLowerCase(); const visibleFeatures = features.map(feature => ({ ...feature, scenarios: feature.scenarios.filter(scenario => !normalized || `${feature.path} ${scenario.name} ${scenario.tags.join(' ')} ${scenario.owner || ''} ${scenario.status || ''} ${scenario.zephyrKey || ''} ${scenario.flakinessTier || ''}`.toLowerCase().includes(normalized)) })).filter(feature => feature.scenarios.length); const scenarioCount = visibleFeatures.reduce((total, feature) => total + feature.scenarios.length, 0); return <section class="area"><div class="area-heading"><div><span class="eyebrow">INVENTORY</span><h1>Test Library</h1><p>Searchable feature and scenario inventory with traceability.</p></div></div><div class="panel feature-tree"><div class="panel-heading"><h2>{featureCount} feature files · {scenarioCount} scenarios</h2><button onClick={() => send('executeExtensionCommand', { commandId: 'karate-dsl.runFolder' })}>Run library</button></div>{visibleFeatures.length ? visibleFeatures.slice(0, 150).map(feature => <details open><summary><span class="codicon codicon-file-code" aria-hidden="true" /><code>{feature.path}</code><span>{feature.scenarios.length} scenario{feature.scenarios.length === 1 ? '' : 's'}</span></summary><table><thead><tr><th>Scenario</th><th>Tags</th><th>Owner</th><th>Status</th><th>Stability</th><th>Zephyr</th><th /></tr></thead><tbody>{feature.scenarios.map(scenario => <tr><td>{scenario.name}</td><td>{scenario.tags.join(' ') || '—'}</td><td>{scenario.owner || '—'}</td><td>{scenario.status || '—'}</td><td>{scenario.flakiness === undefined ? '—' : <span class={`stability stability-${scenario.flakinessTier}`} title={`${scenario.flakinessRuns} recent runs`}>{scenario.flakiness.toFixed(2)} · {scenario.flakinessTier}</span>}</td><td>{scenario.zephyrKey || '—'}</td><td><button class="text-action" onClick={() => send('openScenario', { featurePath: feature.path, line: scenario.line, folderPath })}>Open</button><button class="text-action" onClick={() => setSelected({ ...scenario, path: feature.path })}>Edit</button></td></tr>)}</tbody></table></details>) : <Empty title={query ? 'No indexed test matches' : 'No scenarios discovered'} detail={query ? 'Clear the search or change your search phrase.' : 'Create or import a feature to populate the library.'} />}</div>{selected && <TraceabilityEditor item={selected} folderPath={folderPath} onClose={() => setSelected(undefined)} />}</section>; }
function TraceabilityEditor({ item, folderPath, onClose }: { item: { path: string; name: string; owner?: string; status?: string; zephyrKey?: string }; folderPath?: string; onClose: () => void }) { const [owner, setOwner] = useState(item.owner || ''); const [status, setStatus] = useState(item.status || 'Active'); const [zephyrKey, setZephyrKey] = useState(item.zephyrKey || ''); return <aside class="run-detail" aria-label="Scenario traceability"><div class="panel-heading"><div><h2>{item.name}</h2><p>{item.path}</p></div><button aria-label="Close traceability editor" onClick={onClose}><span class="codicon codicon-close" /></button></div><form class="traceability-form" onSubmit={event => { event.preventDefault(); send('saveTraceability', { featurePath: item.path, scenarioName: item.name, owner, status, zephyrKey, folderPath }); onClose(); }}><label>Owner<input value={owner} onInput={event => setOwner((event.target as HTMLInputElement).value)} /></label><label>Status<select value={status} onChange={event => setStatus((event.target as HTMLSelectElement).value)}><option>Active</option><option>Draft</option><option>Deprecated</option></select></label><label>Zephyr key<input value={zephyrKey} onInput={event => setZephyrKey((event.target as HTMLInputElement).value)} placeholder="e.g. PROJ-T12" /></label><button class="primary-action" type="submit">Save traceability</button></form></aside>; }
function Runs({ runs, profiles, environments, folderPath, runActive }: { runs: Snapshot['runs']; profiles: NonNullable<Snapshot['runProfiles']>; environments: NonNullable<Snapshot['environments']>; folderPath?: string; runActive: boolean }) { const [name, setName] = useState(''); const [environment, setEnvironment] = useState(''); const [parallel, setParallel] = useState('1'); const [selected, setSelected] = useState<NonNullable<Snapshot['runs']>[number]>(); return <section class="area"><div class="area-heading"><div><span class="eyebrow">EXECUTION</span><h1>Runs</h1><p>{runActive ? 'A test run is active. Results will appear here when it completes.' : 'History, profiles, and failure triage in one place.'}</p></div><button class="primary-action" disabled={runActive} onClick={() => send('executeExtensionCommand', { commandId: 'karate-dsl.runFolder' })}>{runActive ? 'Running…' : 'Run all tests'}</button></div><div class="profile-bar"><div><strong>Run profiles</strong><small>{profiles.length ? <span class="profile-list">{profiles.map(profile => <button disabled={runActive} onClick={() => send('runProfile', { id: profile.id, folderPath })}>{profile.name || 'Unnamed'}{profile.environment ? ` · ${profile.environment}` : ''}</button>)}</span> : 'Save repeatable target and environment choices.'}</small></div><label><span class="sr-only">Profile name</span><input value={name} onInput={event => setName((event.target as HTMLInputElement).value)} placeholder="Profile name" /></label><label title="Choose a saved environment or type a new one; new names are saved with the profile."><span class="sr-only">Environment</span><input list="known-environments" value={environment} onInput={event => setEnvironment((event.target as HTMLInputElement).value)} placeholder={environments.length ? `Environment (e.g. ${environments[0].name || ''})` : 'Environment (optional)'} /></label><datalist id="known-environments">{environments.map(item => <option value={item.name || ''} />)}</datalist><label><span class="sr-only">Parallel workers</span><input class="parallel-input" type="number" min="1" value={parallel} onInput={event => setParallel((event.target as HTMLInputElement).value)} /></label><button onClick={() => { if (name.trim()) { send('createRunProfile', { name, environment, parallel: Number(parallel), folderPath }); setName(''); setEnvironment(''); setParallel('1'); } }}>Save profile</button></div><div class="panel data-panel">{runs?.length ? <table><thead><tr><th>Run</th><th>When</th><th>Outcome</th><th>Pass rate</th></tr></thead><tbody>{runs.map(run => <tr class="clickable-row" tabIndex={0} onClick={() => setSelected(run)} onKeyDown={event => { if (event.key === 'Enter' || event.key === ' ') setSelected(run); }}><td>{run.id.slice(0, 8)}</td><td>{new Date(run.timestamp).toLocaleString()}</td><td><span class={`status ${run.status === 'success' ? 'success' : 'failed'}`}>{run.status}</span></td><td>{run.summary?.passPercentage ?? '—'}%</td></tr>)}</tbody></table> : <Empty title="No runs recorded" detail={runActive ? 'Execution is in progress. This table updates as soon as the run is saved.' : 'Run a feature, folder, or tagged selection to build your execution history.'} action={runActive ? undefined : 'Run all tests'} onAction={runActive ? undefined : () => send('executeExtensionCommand', { commandId: 'karate-dsl.runFolder' })} />}</div>{selected && <RunDetail run={selected} folderPath={folderPath} onClose={() => setSelected(undefined)} />}</section>; }
function RunDetail({ run, folderPath, onClose }: { run: NonNullable<Snapshot['runs']>[number]; folderPath?: string; onClose: () => void }) { const failed = run.features?.flatMap(feature => (feature.scenarios || []).filter(scenario => scenario.status !== 'passed').map(scenario => ({ feature, scenario }))) || []; return <aside class="run-detail" aria-label="Run details"><div class="panel-heading"><div><h2>Run {run.id.slice(0, 8)}</h2><p>{run.summary?.executionTime || 'Execution details'} · {run.summary?.passed || 0} passed, {run.summary?.failed || 0} failed</p></div><div class="detail-actions">{run.options && <button class="text-action" onClick={() => send('rerunRun', { options: run.options, folderPath })}><span class="codicon codicon-refresh" aria-hidden="true" /> Rerun</button>}<button aria-label="Close run details" onClick={onClose}><span class="codicon codicon-close" /></button></div></div>{run.error && <p class="run-error">{run.error}</p>}{failed.length ? <ul>{failed.slice(0, 30).map(({ feature, scenario }) => <li><strong>{scenario.name}</strong><small>{feature.relativePath || feature.name}{scenario.error ? ` · ${scenario.error}` : ''}</small><button class="text-action repair-action" onClick={() => send('requestScenarioRepair', { featurePath: feature.relativePath || feature.name, scenarioName: scenario.name, errorMessage: scenario.error || run.error || '', scenarioTags: scenario.tags, scenarioLine: scenario.line, folderPath })}>Review repair</button></li>)}</ul> : <div class="empty"><h3>No failed scenarios recorded</h3><p>This run completed without scenario-level failure details.</p></div>}</aside>; }
function Quality({ findings, coverage, health, folderPath, query }: { findings: NonNullable<Snapshot['findings']>; coverage?: CoverageSnapshot; health?: HealthSnapshot; folderPath?: string; query: string }) { const [state, setState] = useState('Open'); const [source, setSource] = useState('All'); const normalized = query.toLowerCase(); const visible = findings.filter(item => (state === 'All' || (state === 'Open' ? item.state !== 'Verified' : item.state === state)) && (source === 'All' || item.source === source) && (!normalized || `${item.title || ''} ${item.source || ''} ${item.state || ''} ${item.severity || ''}`.toLowerCase().includes(normalized))); const sources = [...new Set(findings.map(item => item.source).filter(Boolean))]; return <section class="area"><div class="area-heading"><div><span class="eyebrow">ASSURANCE</span><h1>Quality</h1><p>Coverage, health, flakiness, and specification change impact.</p></div><div class="quality-actions"><button onClick={() => send('executeExtensionCommand', { commandId: 'karate-dsl.checkSpecChanges' })}>Check spec changes</button><button onClick={() => send('executeExtensionCommand', { commandId: 'karate-dsl.analyzeProjectHealth' })}>Analyse health</button><button class="primary-action" onClick={() => send('analyzeCoverage', { folderPath })}>Analyse coverage</button></div></div>{health && <HealthReport report={health} />}{coverage && <CoverageReport report={coverage} />}{findings.length > 0 && <div class="filter-bar"><label>State <select value={state} onChange={event => setState((event.target as HTMLSelectElement).value)}><option>Open</option><option>All</option><option>New</option><option>Investigating</option><option>Fixed</option><option>Verified</option></select></label><label>Source <select value={source} onChange={event => setSource((event.target as HTMLSelectElement).value)}><option>All</option>{sources.map(value => <option>{value}</option>)}</select></label><span>{visible.length} finding{visible.length === 1 ? '' : 's'}</span></div>}<div class="panel data-panel">{visible.length ? <table><thead><tr><th>Finding</th><th>Source</th><th>State</th><th>Severity</th><th /></tr></thead><tbody>{visible.map(item => { const next = nextQualityState(item.state || 'New'); return <tr><td>{item.title || item.id}</td><td>{item.source || 'manual'}</td><td>{item.state || 'New'}</td><td>{item.severity || 'Normal'}</td><td>{next && <button class="text-action" onClick={() => send('advanceQualityFinding', { id: item.id, nextState: next, folderPath })}>Mark {next}</button>}</td></tr>; })}</tbody></table> : <Empty title={findings.length ? 'No findings match these filters' : 'No quality findings yet'} detail={findings.length ? 'Adjust the filters or global search to see more work.' : 'Analyse coverage or project health to start a managed quality queue.'} action={findings.length ? undefined : 'Analyse health'} onAction={findings.length ? undefined : () => send('executeExtensionCommand', { commandId: 'karate-dsl.analyzeProjectHealth' })} />}</div></section>; }
function HealthReport({ report }: { report: HealthSnapshot }) { return <section class="health-report panel"><div class="panel-heading"><div><h2>Project health</h2><p>Dependency and reuse signals from the current workspace.</p></div><span class="status-pill">Fresh analysis</span></div><div class="health-metrics"><Metric label="Feature files" value={String(report.totalFiles)} note="Indexed feature files" /><Metric label="Scenarios" value={String(report.totalScenarios)} note="Across the project" /><Metric label="Reusability" value={`${report.dryScore}%`} note={`${report.dependencyCount} feature dependencies`} /><Metric label="Potentially unused" value={String(report.orphanedFiles.length)} note="Reusable files with no callers" emphasis={report.orphanedFiles.length > 0} /></div>{report.orphanedFiles.length > 0 && <div class="health-orphans"><strong>Review unused reusable features</strong><span>{report.orphanedFiles.slice(0, 12).join(' · ')}</span></div>}</section>; }
function CoverageReport({ report }: { report: CoverageSnapshot }) { const uncovered = report.endpoints.filter(endpoint => !endpoint.covered); return <section class="coverage-report panel"><div class="panel-heading"><div><h2>Coverage · {report.specName}</h2><p>{report.coveredEndpoints} of {report.totalEndpoints} endpoints covered</p></div><strong class="coverage-percentage">{report.percentage.toFixed(1)}%</strong></div><div class="coverage-methods">{report.methodBreakdown.map(method => <div><strong>{method.method}</strong><span>{method.covered}/{method.total} · {method.percentage.toFixed(0)}%</span></div>)}</div>{uncovered.length > 0 ? <div class="data-panel coverage-gaps"><table><thead><tr><th>Uncovered endpoint</th><th>Suggested coverage</th></tr></thead><tbody>{uncovered.slice(0, 50).map(endpoint => <tr><td><code>{endpoint.method.toUpperCase()} {endpoint.path}</code></td><td>{endpoint.missingTests.slice(0, 2).join(' · ') || 'Add a Karate scenario'}</td></tr>)}</tbody></table></div> : <div class="coverage-clear"><span class="codicon codicon-pass" aria-hidden="true" /> Every endpoint in this report has matching coverage.</div>}</section>; }
function nextQualityState(state: string): string | undefined { return ({ New: 'Investigating', Investigating: 'Fixed', Fixed: 'Verified' } as Record<string, string>)[state]; }
function Create({ templates, selectedFile, generatedOutput, onFileConsumed }: { templates: TemplateOption[]; selectedFile: string; generatedOutput?: GeneratedOutput; onFileConsumed: () => void }) {
    const sources = [
        { id: 'openapi', label: 'OpenAPI specification', detail: 'JSON or YAML contract', icon: 'file-code', tone: 'blue', command: 'karate-dsl.generateFromOpenAPI' },
        { id: 'combined', label: 'OpenAPI + Confluence', detail: 'Contract plus requirements', icon: 'combine', tone: 'cyan', command: 'karate-dsl.generateCombined' },
        { id: 'confluence', label: 'Confluence page', detail: 'Requirements to coverage', icon: 'book', tone: 'green', command: 'karate-dsl.generateFromConfluence' },
        { id: 'postman', label: 'Postman collection', detail: 'Convert an existing collection', icon: 'archive', tone: 'orange', command: 'karate-dsl.importPostmanCollection' },
        { id: 'har', label: 'HAR recording', detail: 'Import a captured browser flow', icon: 'globe', tone: 'amber', command: 'karate-dsl.importHar' },
        { id: 'graphql', label: 'GraphQL schema', detail: 'Query and mutation tests', icon: 'symbol-method', tone: 'purple', command: 'karate-dsl.generateFromGraphQL' }
    ] as const;
    const [sourceId, setSourceId] = useState<typeof sources[number]['id']>();
    const [filePath, setFilePath] = useState('');
    const [pageUrl, setPageUrl] = useState('');
    const [useCopilot, setUseCopilot] = useState(false);
    const [templateId, setTemplateId] = useState('');
    const [instruction, setInstruction] = useState('');
    const [scenarioTypes, setScenarioTypes] = useState<string[]>(['positive', 'negative', 'edge', 'security']);
    const [methods, setMethods] = useState<string[]>([]);
    const selected = sources.find(source => source.id === sourceId);

    useEffect(() => { if (selectedFile) { setFilePath(selectedFile); onFileConsumed(); } }, [selectedFile, onFileConsumed]);
    const toggle = (value: string, current: string[], set: (next: string[]) => void) => set(current.includes(value) ? current.filter(item => item !== value) : [...current, value]);
    const chooseFile = () => send('selectOpenAPIFile');
    const generate = () => {
        if (!selected) return;
        if (selected.id === 'openapi') send('generateFromOpenAPI', { filePath, useCopilot, templateId: templateId || undefined, scenarioTypes, httpMethods: methods, customInstruction: instruction || undefined });
        else if (selected.id === 'combined') send('generateCombined', { openApiPath: filePath, confluenceUrl: pageUrl, useCopilot, templateId: templateId || undefined, scenarioTypes, httpMethods: methods, customInstruction: instruction || undefined });
        else if (selected.id === 'confluence') send('generateFromConfluence', { pageUrl, useCopilot, templateId: templateId || undefined });
        else send('executeExtensionCommand', { commandId: selected.command });
    };
    return <section class="area create-area"><div class="area-heading"><div><span class="eyebrow">AUTHORING</span><h1>Generate and import</h1><p>Choose a source. Options appear on the next step.</p></div></div>
        {!selected ? <><div class="source-grid">{sources.map(source => <button class="source-card" onClick={() => setSourceId(source.id)}><span class={`source-card-icon tone-${source.tone} codicon codicon-${source.icon}`} aria-hidden="true" /><span class="source-card-copy"><strong>{source.label}</strong><small>{source.detail}</small></span><span class="codicon codicon-arrow-right source-card-arrow" aria-hidden="true" /></button>)}</div><div class="panel generation-defaults"><span class="eyebrow">SCENARIO TYPES · STEP 2</span><div class="choice-row">{['positive', 'negative', 'security'].map(value => <label><input type="checkbox" checked={scenarioTypes.includes(value)} onChange={() => toggle(value, scenarioTypes, setScenarioTypes)} /> {value}</label>)}<label><input type="checkbox" checked={useCopilot} onChange={event => setUseCopilot((event.target as HTMLInputElement).checked)} /> AI enhancement</label></div></div></> : <div class="generator-workbench"><div class="generator-header"><button class="text-action" onClick={() => setSourceId(undefined)}><span class="codicon codicon-arrow-left" aria-hidden="true" /> All sources</button><strong><span class={`codicon codicon-${selected.icon}`} aria-hidden="true" /> {selected.label}</strong></div>{(selected.id === 'openapi' || selected.id === 'combined') && <label class="source-input">OpenAPI file<div><input value={filePath} readOnly placeholder="Choose an OpenAPI JSON or YAML file" /><button type="button" onClick={chooseFile}>Browse</button></div></label>}{(selected.id === 'confluence' || selected.id === 'combined') && <label class="source-input">Confluence page URL<input value={pageUrl} onInput={event => setPageUrl((event.target as HTMLInputElement).value)} placeholder="https://your-team.atlassian.net/wiki/..." /></label>}{['openapi', 'combined'].includes(selected.id) && <><fieldset class="option-group"><legend>Scenario coverage</legend><div class="choice-row">{['positive', 'negative', 'edge', 'security'].map(value => <label><input type="checkbox" checked={scenarioTypes.includes(value)} onChange={() => toggle(value, scenarioTypes, setScenarioTypes)} /> {value}</label>)}</div></fieldset><fieldset class="option-group"><legend>HTTP methods <small>All methods when nothing is selected</small></legend><div class="choice-row">{['get', 'post', 'put', 'patch', 'delete'].map(value => <label><input type="checkbox" checked={methods.includes(value)} onChange={() => toggle(value, methods, setMethods)} /> {value.toUpperCase()}</label>)}</div></fieldset></>}<div class="generator-options"><label><input type="checkbox" checked={useCopilot} onChange={event => setUseCopilot((event.target as HTMLInputElement).checked)} /> Enhance this run with AI</label><label>Template<select value={templateId} onChange={event => setTemplateId((event.target as HTMLSelectElement).value)}><option value="">Workspace default</option>{templates.map(template => <option value={template.id}>{template.name}</option>)}</select></label></div>{['openapi', 'combined'].includes(selected.id) && <label class="source-input">Custom instruction<textarea value={instruction} onInput={event => setInstruction((event.target as HTMLTextAreaElement).value)} placeholder="Optional guidance for this generation run" rows={3} /></label>}<button class="primary-action generate-action" disabled={(selected.id === 'openapi' && !filePath) || (selected.id === 'combined' && (!filePath || !pageUrl)) || (selected.id === 'confluence' && !pageUrl)} onClick={generate}><span class="codicon codicon-play" aria-hidden="true" /> Generate tests</button></div>}{generatedOutput && <div class="generation-result panel"><div><strong>{generatedOutput.message}</strong><span>{generatedOutput.filePath}</span></div><div><button onClick={() => send('openGeneratedFile', { filePath: generatedOutput.filePath })}>Open file</button><button onClick={() => send('copyToClipboard', { content: generatedOutput.content })}>Copy output</button></div></div>}</section>;
}
function Operations({ bugHunter, onNavigate, templates, history, hasLearnedStyle }: { bugHunter?: BugHunterSnapshot; onNavigate: (area: Area) => void; templates: TemplateOption[]; history: GenerationHistoryItem[]; hasLearnedStyle: boolean }) { return <section class="area"><div class="area-heading"><div><span class="eyebrow">OPERATIONS</span><h1>Operations</h1><p>Investigate live APIs, personalise generation, and manage integrations.</p></div></div>{bugHunter && <BugHunterReport report={bugHunter} />}<div class="panel operations-list"><Operation title="API Bug Hunter" detail="Run bounded, allowlisted probes against an API specification." action="Start Bug Hunter" command="karate-dsl.huntApiBugs" /><Operation title="CI repair queue" detail="Review CI failures in Quality and apply AI suggestions only after confirmation." action="Review queue" onAction={() => onNavigate('quality')} /><Operation title="Zephyr publishing" detail="Set the Zephyr credential used for publishing traceability and results." action="Set Zephyr token" command="karate-dsl.setZephyrToken" /><Operation title="AI credentials" detail="Set the AI provider or GitHub credential used by generation and repair." action="Set AI key" command="karate-dsl.setClaudeApiKey" /><Operation title="MCP connection" detail="View the MCP connection details for supported automation clients." action="View connection" command="karate-dsl.showMcpConnectionInfo" /><Operation title="Workspace settings" detail="Manage execution and integration preferences." action="Open settings" command="workbench.action.openSettings" /><Operation title="Bug reporting" detail="Open a prefilled GitHub issue with optional context. No usage telemetry is collected." action="Report a bug" onAction={() => send('reportBug', { activeArea: 'operations' })} /></div><Personalize templates={templates} history={history} hasLearnedStyle={hasLearnedStyle} /></section>; }
function Personalize({ templates, history, hasLearnedStyle }: { templates: TemplateOption[]; history: GenerationHistoryItem[]; hasLearnedStyle: boolean }) { const [name, setName] = useState(''); const [content, setContent] = useState(''); const save = () => { if (name.trim() && content.trim()) { send('saveTemplate', { template: { id: `custom-${Date.now()}`, name: name.trim(), content, description: 'Custom workspace template' } }); setName(''); setContent(''); } }; return <section class="personalize panel"><div class="panel-heading"><div><h2>Personalize generation</h2><p>{hasLearnedStyle ? 'A learned Karate style will be used for future generations.' : 'Use an existing feature to teach the generator your suite conventions.'}</p></div><button class="text-action" onClick={() => send('learnStyle')}>{hasLearnedStyle ? 'Learn again' : 'Learn from feature'}</button></div><div class="template-form"><label>New template name<input value={name} onInput={event => setName((event.target as HTMLInputElement).value)} placeholder="e.g. Payment API baseline" /></label><label>Template content<textarea value={content} onInput={event => setContent((event.target as HTMLTextAreaElement).value)} placeholder="Feature: {{featureName}}&#10;{{scenarios}}" rows={4} /></label><button disabled={!name.trim() || !content.trim()} onClick={save}>Save template</button></div><div class="personalize-summary"><div><strong>{templates.length} templates</strong><span>{templates.map(template => template.name).join(' · ')}</span></div><div><strong>{history.length} recent generations</strong><span>{history.length ? history.slice(0, 3).map(item => `${item.type} · ${item.source}`).join(' · ') : 'Generated files will appear here.'}</span></div></div></section>; }
function BugHunterReport({ report }: { report: BugHunterSnapshot }) { return <section class="bug-hunter-report panel"><div class="panel-heading"><div><h2>Bug Hunter · {report.baseUrl}</h2><p>{report.executedProbes} executed, {report.skippedProbes} skipped · {new Date(report.completedAt).toLocaleString()}</p></div><strong class={report.findings.length ? 'finding-total has-findings' : 'finding-total'}>{report.findings.length} finding{report.findings.length === 1 ? '' : 's'}</strong></div><div class="bug-metrics"><Metric label="Probe candidates" value={String(report.totalProbes)} note="Built from this specification" /><Metric label="Executed" value={String(report.executedProbes)} note="Within configured limits" /><Metric label="Skipped" value={String(report.skippedProbes)} note="Guardrails or preconditions" /><Metric label="Repro feature" value={report.reproFile ? 'Ready' : '—'} note={report.reproFile || 'No repro created'} /></div>{report.findings.length ? <div class="data-panel"><table><thead><tr><th>Finding</th><th>Endpoint</th><th>Observed</th></tr></thead><tbody>{report.findings.map(finding => <tr><td><span class={`status severity-${finding.severity}`}>{finding.severity}</span> {finding.category}</td><td><code>{finding.method} {finding.path}</code></td><td>{finding.observed}</td></tr>)}</tbody></table></div> : <div class="coverage-clear"><span class="codicon codicon-pass" aria-hidden="true" /> No issues were detected by the executed probes.</div>}</section>; }
function Operation({ title, detail, action, command, onAction }: { title: string; detail: string; action: string; command?: string; onAction?: () => void }) { return <article class="operation"><h2>{title}</h2><p>{detail}</p><button onClick={onAction || (() => { if (command) send('executeExtensionCommand', { commandId: command }); })}>{action} <span class="codicon codicon-arrow-right" /></button></article>; }
function Empty({ title, detail, action, onAction }: { title: string; detail: string; action?: string; onAction?: () => void }) { return <div class="empty"><span class="codicon codicon-checklist" aria-hidden="true" /><h3>{title}</h3><p>{detail}</p>{action && <button onClick={onAction}>{action}</button>}</div>; }

render(<App />, document.getElementById('root')!);
